import hashlib, math, secrets

SMALL_PRIMES = [p for p in range(3, 2000) if all(p % d for d in range(2, int(p ** 0.5) + 1))]

def probably_prime(n, rounds=40):
    if any(n % p == 0 for p in SMALL_PRIMES):
        return n in SMALL_PRIMES
    d, r = n - 1, 0
    while d % 2 == 0:
        d, r = d // 2, r + 1
    for _ in range(rounds):                              # Miller-Rabin
        x = pow(secrets.randbelow(n - 3) + 2, d, n)
        if x in (1, n - 1):
            continue
        for _ in range(r - 1):
            x = x * x % n
            if x == n - 1:
                break
        else:
            return False
    return True

def random_prime(bits):
    while True:
        candidate = secrets.randbits(bits) | (3 << (bits - 2)) | 1      # top two bits set so n has exactly 2*bits bits
        if probably_prime(candidate):
            return candidate

def keygen():
    e = 65537
    while True:
        p, q = random_prime(1024), random_prime(1024)
        if p != q and math.gcd(e, (p - 1) * (q - 1)) == 1:
            return (p * q, e), pow(e, -1, (p - 1) * (q - 1))          # (public key), private exponent

def derive(x, n):
    return hashlib.sha3_256(x.to_bytes((n.bit_length() + 7) // 8, "big")).digest()

def encaps(public_key):
    n, e = public_key
    x = secrets.randbelow(n - 3) + 2                    # random element, never chosen by a person
    return derive(x, n), pow(x, e, n)                   # (shared secret, ciphertext)

def decaps(public_key, d, ciphertext):
    n, _ = public_key
    return derive(pow(ciphertext, d, n), n)

public_key, d = keygen()
shared_a, ciphertext = encaps(public_key)
shared_b = decaps(public_key, d, ciphertext)
print("modulus bits:", public_key[0].bit_length())
print("ciphertext bytes:", (ciphertext.bit_length() + 7) // 8, "(at most 256)")
print("shared secret bytes:", len(shared_a))
print("both sides derived the same secret:", shared_a == shared_b)

import hashlib, secrets

def H(data):
    return hashlib.sha256(data).digest()

def digest_bits(message):
    d = H(message)
    return [(d[i // 8] >> (7 - i % 8)) & 1 for i in range(256)]

def keygen():
    private = [[secrets.token_bytes(32), secrets.token_bytes(32)] for _ in range(256)]
    public = [[H(y0), H(y1)] for y0, y1 in private]
    return private, public

def sign(private, message):
    return [private[i][bit] for i, bit in enumerate(digest_bits(message))]

def verify(public, message, signature):
    return all(H(value) == public[i][bit] for i, (value, bit) in enumerate(zip(signature, digest_bits(message))))

private, public = keygen()
signature = sign(private, b"transfer 100 to alice")
print("private key bytes:", sum(len(y) for pair in private for y in pair))
print("public key bytes: ", sum(len(z) for pair in public for z in pair))
print("signature bytes:  ", sum(len(v) for v in signature))
print("valid message verifies:", verify(public, b"transfer 100 to alice", signature))
print("changed message verifies:", verify(public, b"transfer 900 to alice", signature))

revealed = set()
for n in range(1, 6):
    message = f"message number {n}".encode()
    revealed |= {(i, bit) for i, bit in enumerate(digest_bits(message))}
    print(f"after {n} signature(s) with the same key: {len(revealed) / 512:.1%} of the private key is revealed")

import hashlib

def h(data):
    return hashlib.sha256(data).digest()

d = 4
keys = {i: f"one-time public key {i}".encode() for i in range(1, 2 ** d + 1)}     # stand-ins for real one-time public keys
V = {}
for j in range(2 ** d, 2 ** (d + 1)):
    V[j] = h(keys[j - 2 ** d + 1])                                 # leaf node j holds h(K_(j-15))
for j in range(2 ** d - 1, 0, -1):
    V[j] = h(V[2 * j] + V[2 * j + 1])                              # inner node: hash of its two children
root = V[1]                                                         # the public key

def auth_path(i):
    node, path = i + 2 ** d - 1, []
    while node > 1:
        path.append(node ^ 1)                                       # sibling: node +/- 1
        node //= 2
    return path

def verify(i, key, siblings):
    node, value = i + 2 ** d - 1, h(key)
    for sibling_node, sibling_value in siblings:
        value = h(value + sibling_value) if node % 2 == 0 else h(sibling_value + value)
        node //= 2
    return value == root

path = auth_path(11)
print("leaf node for K11:", 11 + 2 ** d - 1, " sibling nodes in the authentication path:", path)
siblings = [(node, V[node]) for node in path]
print("K11 authenticates against the root:", verify(11, keys[11], siblings))
print("a different key at position 11 authenticates:", verify(11, b"another key", siblings))
print("hash operations to verify:", len(path) + 1, "; leaves in the tree:", 2 ** d)

r = 11
MASK = (1 << r) - 1

def poly(*exponents):
    return sum(1 << e for e in exponents)
def show(p):
    terms = [("1" if e == 0 else "x" if e == 1 else f"x^{e}") for e in range(r - 1, -1, -1) if p >> e & 1]
    return " + ".join(terms)
def mul(a, b):                                                       # product in GF(2)[x]/(x^r - 1)
    out = 0
    for i in range(r):
        if a >> i & 1:
            out ^= ((b << i) | (b >> (r - i))) & MASK
    return out
def inverse(a):
    return next(c for c in range(1, 1 << r) if mul(a, c) == 1)

h0, h1 = poly(9, 5, 4), poly(10, 1, 0)
h0_inv = inverse(h0)
h = mul(h1, h0_inv)                                                  # public key
print("h0^-1 =", show(h0_inv))
print("h     =", show(h))

e0, e1 = poly(3), poly(4, 7, 10)                                     # plaintext of total weight t = 4
s = e0 ^ mul(e1, h)                                                  # ciphertext
print("s     =", show(s))
m = mul(s, h0)
print("s*h0  =", show(m))
print("equals e0*h0 + e1*h1:", m == mul(e0, h0) ^ mul(e1, h1))

from itertools import product

def f(x):
    x1, x2, x3, x4 = x
    return (x1 * x2 ^ x2 * x3 ^ x4, x1 * x3 ^ x2 * x4 ^ x2)           # secret system: no product of two oil variables (x3, x4)

def S(x):
    x1, x2, x3, x4 = x
    return (x2 ^ x4 ^ 1, x1 ^ x4 ^ 1, x2 ^ x3 ^ x4, x1 ^ x2 ^ x3 ^ x4)
def S_inverse(y):
    y1, y2, y3, y4 = y
    return (y3 ^ y4, y1 ^ y2 ^ y3 ^ y4, y1 ^ y3 ^ 1, y2 ^ y3 ^ y4 ^ 1)

def f_pub(x):
    return f(S(x))                                                    # the public key is the disguised system

points = list(product((0, 1), repeat=4))
print("S_inverse really inverts S:", all(S_inverse(S(p)) == p for p in points))

def slide_f1(x1, x2, x3, x4): return x1 * x3 ^ x3 * x4 ^ x2 ^ 1
def slide_f2(x1, x2, x3, x4): return x1 * x2 ^ x1 * x3 ^ x2 * x3 ^ x2 * x4 ^ x1 ^ x2 ^ x4 ^ 1
print("public polynomials equal the ones printed on the slide:", all(f_pub(p) == (slide_f1(*p), slide_f2(*p)) for p in points))

def sign(message):
    for vinegar in product((0, 1), repeat=2):                          # guess the vinegar variables
        for oil in product((0, 1), repeat=2):                          # with vinegar fixed the system is linear in the oil variables
            if f(vinegar + oil) == message:
                return S_inverse(vinegar + oil)
    return None

signature = sign((0, 1))
print("signature for message (0,1):", signature)
print("public verification f_pub(signature) =", f_pub(signature))
print("signatures that would verify for (0,1) (found by exhaustive search):", [p for p in points if f_pub(p) == (0, 1)])

import hashlib, secrets

BITS = 16                                                            # toy digest length: first 2 bytes of SHA-256
def digest_bits(message):
    d = hashlib.sha256(message).digest()
    return [(d[i // 8] >> (7 - i % 8)) & 1 for i in range(BITS)]
def hash_(value):
    return hashlib.sha256(value).digest()

private = [[secrets.token_bytes(32), secrets.token_bytes(32)] for _ in range(BITS)]
public = [[hash_(a), hash_(b)] for a, b in private]

def sign(message):
    return [private[i][bit] for i, bit in enumerate(digest_bits(message))]
def verify(message, signature):
    return all(hash_(v) == public[i][bit] for i, (v, bit) in enumerate(zip(signature, digest_bits(message))))

revealed = {}                                                        # (position, bit) -> value an eavesdropper has seen
for n in range(1, 5):
    message = f"status update {n}".encode()
    for i, v in enumerate(sign(message)):
        revealed[(i, digest_bits(message)[i])] = v

    attempts, target = 0, None
    while target is None:
        attempts += 1
        candidate = f"forged message {attempts}".encode()
        if all((i, bit) in revealed for i, bit in enumerate(digest_bits(candidate))):
            target = candidate
    forged = [revealed[(i, bit)] for i, bit in enumerate(digest_bits(target))]
    print(f"{n} signed message(s): forged {target.decode()!r} after {attempts:>6} attempts, verifies: {verify(target, forged)}")

class OneTimeSigner:
    def __init__(self):
        self.used = False
    def sign(self, message):
        if self.used:
            raise RuntimeError("one-time key already used: refuse to sign")
        self.used = True
        return sign(message)

signer = OneTimeSigner()
signer.sign(b"first message")
try:
    signer.sign(b"second message")
except RuntimeError as error:
    print("stateful signer:", error)
